questions=[]
def add(level,topic,prompt,answer,explanation,page=0,aliases=(),options=(),kind=None,numeric=False,board=(),source=''):
    q=Question(id=f'{topic}-{level}-{sum(q.level==level and topic in q.topics for q in questions)+1:02}',level=level,topics=[topic],kind=kind or ('choice' if level==1 else 'short'),prompt=prompt,answer=answer,explanation=explanation,aliases=list(aliases),options=list(options),source=source or ('Правила Школы 21' if page else 'Авторская задача по явно заданным условиям'),page=page,numeric_set=numeric,board=list(board))
    q.validate();questions.append(q)
def easy(topic,prompt,options,explanation,page=0):
    add(1,topic,prompt,options[0],explanation,page,options=options)
def medium(topic,prompt,answer,explanation,page=0,aliases=(),**kw):add(2,topic,prompt,answer,explanation,page,aliases,**kw)
def hard(topic,prompt,answer,explanation,page=0,aliases=(),**kw):add(3,topic,prompt,answer,explanation,page,aliases,**kw)

